def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    col_list = list(columns)
    seen = set()
    for col in col_list:
        if not isinstance(col, str):
            raise ValueError("Column names must be strings")
        if col in seen:
            raise ValueError("Duplicate column names are not allowed")
        seen.add(col)

    def format_value(value):
        if value is None:
            return ""
        text = str(value)
        if any(ch in text for ch in [',', '"', '\n', '\r']):
            text = text.replace('"', '""')
            text = '"' + text + '"'
        return text

    lines = []
    lines.append(",".join(format_value(col) for col in col_list))
    for row in rows:
        lines.append(",".join(format_value(row.get(col, "")) for col in col_list))
    return "\r\n".join(lines) + "\r\n"

